import java.util.Scanner;

class Printer {
    public void printDocument(String documentType) {
        System.out.println("Printing " + documentType);
    }
}

class LaserPrinter extends Printer {
    private void printDocument(String documentType) {
        System.out.println("Laser printing " + documentType);
    }
}
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        String documentType = sc.nextLine();

        Printer p = new LaserPrinter();
        p.printDocument(documentType);

        sc.close();
    }
}

